static const uint16_t* const egg_frames[2] = { egg_frame0, egg_frame1 };
static const uint8_t egg_frame_count = 2;

// ==========================================
// Stage Sprites Lookup
// ==========================================
inline const uint16_t* getStageFrame(uint8_t stage, uint8_t frameIdx = 0) {
    switch (stage) {
        case 0:
            return egg_frames[frameIdx % egg_frame_count];
        case 1:
            return cerato_lv1_frames[frameIdx % cerato_lv1_frame_count];
        case 2:
            return cerato_lv2_frames[frameIdx % cerato_lv2_frame_count];
        case 3:
            return cerato_lv3_frames[frameIdx % cerato_lv3_frame_count];
        case 4:
            return cerato_lv4_frames[frameIdx % cerato_lv4_frame_count];
        case 5:
            return cerato_lv5_frames[frameIdx % cerato_lv5_frame_count];
        case 6:
            return cerato_lv6_frames[frameIdx % cerato_lv6_frame_count];
        case 7:
            return cerato_lv7_frames[frameIdx % cerato_lv7_frame_count];
        default:
            return cerato_lv1_frames[0];
    }
}

inline uint8_t getStageFrameCount(uint8_t stage) {
    switch (stage) {
        case 0:
            return egg_frame_count;
        case 1:
            return cerato_lv1_frame_count;
        case 2:
            return cerato_lv2_frame_count;
        case 3:
            return cerato_lv3_frame_count;
        case 4:
            return cerato_lv4_frame_count;
        case 5:
            return cerato_lv5_frame_count;
        case 6:
            return cerato_lv6_frame_count;
        case 7:
            return cerato_lv7_frame_count;
        default:
            return 1;
    }
}

